// Generated by AI (UnitTest MCP)
//! PostgreSQL-gated route coverage for the read-only supervisor dashboard page.

mod supervisor_api_support;

use ackplane_server::supervisor_store::SupervisorStore;
use axum::{
    body::{to_bytes, Body},
    http::{Request, StatusCode},
};
use serde_json::json;
use supervisor_api_support::{
    application, body_json, enroll_repository, registration, unique_id, unix_seconds,
};
use tower::ServiceExt;

#[tokio::test]
async fn supervisor_dashboard_is_a_read_only_runtime_inspection_page() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("dashboard");
    let tenant_id = format!("tenant-dashboard-{unique}");
    let repository_id = format!("repository-dashboard-{unique}");
    let node_id = enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;
    let supervisor_id = format!("supervisor-dashboard-{unique}");
    let mut supervisors = SupervisorStore::connect(&database_url)
        .await
        .expect("connect Supervisor store for dashboard fixtures");
    let registered = supervisors
        .register(&registration(
            &tenant_id,
            &repository_id,
            &node_id,
            supervisor_id.clone(),
        ))
        .await
        .expect("register supervisor for dashboard inventory");
    let app = application(&database_url, &tenant_id).await;
    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/supervisors")
                .body(Body::empty())
                .expect("build supervisor dashboard request"),
        )
        .await
        .expect("serve supervisor dashboard route");

    assert_eq!(response.status(), StatusCode::OK);
    let body = String::from_utf8(
        to_bytes(response.into_body(), 1_048_576)
            .await
            .expect("read supervisor dashboard body")
            .to_vec(),
    )
    .expect("supervisor dashboard is valid UTF-8");
    for required in [
        "Supervisor runtime",
        "id=\"repository\"",
        "REFRESH_INTERVAL_MS = 15_000",
        "document.visibilityState === \"visible\"",
        "/supervisors",
        "/sessions",
        "/lifecycle",
        "outbox_durability",
        "recoverable_outbox",
        "supported_directives",
    ] {
        assert!(
            body.contains(required),
            "supervisor dashboard must render {required}"
        );
    }
    for forbidden in ["idempotency_key", "method:", "POST", "process tree"] {
        assert!(
            !body.contains(forbidden),
            "supervisor dashboard must not expose or invoke {forbidden}"
        );
    }

    let inventory = app
        .oneshot(
            Request::builder()
                .uri(format!("/api/v1/repositories/{repository_id}/supervisors"))
                .body(Body::empty())
                .expect("build dashboard inventory request"),
        )
        .await
        .expect("serve dashboard inventory route");
    assert_eq!(inventory.status(), StatusCode::OK);
    assert_eq!(
        body_json(inventory).await,
        json!({
            "entries": [{
                "supervisor_id": supervisor_id,
                "node_id": node_id,
                "supervisor_version": "1.0.0",
                "protocol_version": "v1",
                "supported_directives": ["notify", "terminate_force"],
                "supports_checkpoint": true,
                "supports_force_termination": true,
                "outbox_durability": "persistent",
                "recoverable_outbox": true,
                "registered_at_seconds": unix_seconds(registered.status.registered_at),
                "last_heartbeat_at_seconds": null,
                "freshness": "never_reported"
            }]
        })
    );
}
